"""PreToolUse hook: refuse edits to generated files and say what to change instead (exit 2 = block, stderr goes to Claude)."""
import json
import os
import sys
from pathlib import Path

RULES = [  # (path prefix, what to do instead); data/ and mcp/ are clones of a3ref/data and a3ref/mcp
    ("out/", "out/ is generated by `python -m biwiki build`; change the code in biwiki/ and rebuild."),
    ("tests/fixtures/raw/", "Fixtures are copies of real wiki pages; regenerate them with `python tests/fixtures/refresh.py`."),
    ("data/schema.json", "schema.json in the data clone is copied from biwiki/schema.json by the build; edit that one."),
    ("data/raw/", "raw/ in the data clone is the wikitext cache written by `python -m biwiki sync`; never edit it by hand."),
    ("data/", "The a3ref/data clone holds generated JSON; change the parser in biwiki/ and run "
              "`python -m biwiki --dataset <clone> build`. Only its README.md, AGENTS.md, CLAUDE.md and .github/ are hand-written."),
    ("mcp/dist/", "dist/ in a3ref/mcp is the bundle built from its src/; edit src/ and run `npm run build` there."),
]
HAND_WRITTEN = ("data/README.md", "data/.gitattributes", "data/AGENTS.md", "data/CLAUDE.md", "data/.github/", "data/.claude/")

event = json.load(sys.stdin)
path = event.get("tool_input", {}).get("file_path")
if not path:
    sys.exit(0)
root = Path(os.environ.get("CLAUDE_PROJECT_DIR") or event.get("cwd") or ".").resolve()
target = Path(path).resolve()
try:
    rel = target.relative_to(root).as_posix()
except ValueError:  # clones next to this repository are checked as data/... and mcp/... too
    try:
        rel = target.relative_to(root.parent).as_posix()
    except ValueError:
        sys.exit(0)
    if not rel.startswith(("data/", "mcp/")):
        sys.exit(0)
if rel.startswith(HAND_WRITTEN):
    sys.exit(0)
for prefix, advice in RULES:
    if rel == prefix or rel.startswith(prefix):
        print(f"Blocked: {rel}. {advice}", file=sys.stderr)
        sys.exit(2)
